2. instanceof:instanceof 运算符用于检测构造函数的 prototype 属性是否出现在某个实例对象的原型链上;使用;object instanceof constructor;object为实例对象，constructor为构造函数;构造函数通过new可以实例对象，instanceof 能判断这个对象是否是之前那个构造函数生成的对象;// 定义构建函数;let Car = function() {};let benz = new Car();benz instanceof Car // true;let car = new String('xxx');car instanceof String // true;let str = 'xxx';str instanceof String // false;关于instanceof的实现原理，可:function myInstanceof(left, right) {;// 这里先用typeof来判断基础数据类型，如果是，直接返回false;if(typeof left !== 'object' left === null) return false;;// getProtypeOf是Object对象自带的API，能够拿到参数的原型对象;let proto = Object.getPrototypeOf(left);;while(true) {;if(proto === null) return false;;if(proto === right.prototype) return true;//找到相同原型对象，返回true;proto = Object.getPrototypeof(proto);;};};也就是顺着原型链去找，直到找到相同的原型对象，返回true，否则为false

